style.css:
@-moz-document domain("roblox.com") {
/* Set overall page background and font */
    body {
        background-color: #f2f2f2 !important;
        font-family: Verdana, sans-serif !important;
    }

    /* Navigation Bar (red top bar) */
    nav, .navbar, .header, #navigation {
        background-color: #c40000 !important;
        color: white !important;
        border-bottom: 2px solid #8a0000 !important;
    }

    nav a, .navbar a, .header a {
        color: white !important;
        font-weight: bold !important;
        font-family: Verdana, sans-serif !important;
        text-transform: none !important;
    }

    /* Buttons styled like 2010 */
    .btn, button, input[type="submit"] {
        background-color: #c40000 !important;
        border: 1px solid #8a0000 !important;
        color: white !important;
        font-family: Verdana, sans-serif !important;
        padding: 4px 10px !important;
    }

    /* Remove rounded modern elements */
    .rounded, .card, .tile, .container {
        border-radius: 0 !important;
        box-shadow: none !important;
        background-color: white !important;
    }

    /* Titles and headers */
    h1, h2, h3 {
        color: #c40000 !important;
        font-family: Verdana, sans-serif !important;
    }

    /* Classic Roblox logo replacement */
    .navbar-brand img {
        content: url("https://upload.wikimedia.org/wikipedia/en/thumb/e/e0/Roblox_Logo_2010.svg/320px-Roblox_Logo_2010.svg.png") !important;
        height: 40px !important;
    }

    /* Footer bar */
    footer {
        background-color: #c40000 !important;
        color: white !important;
    }
}
